'use server'

import { revalidatePath } from 'next/cache'

// In-memory store for the notification preference. In a real app this would
// be a database call scoped to the authenticated user. It persists across
// Server Action invocations within the same server process.
const preference = { notificationsEnabled: false }

export async function getNotificationPreference() {
  return preference.notificationsEnabled
}

/**
 * Toggles the current user's notification preference between on and off.
 *
 * After mutating the preference, we call `revalidatePath` with the current
 * page path. This is Next.js's recommended way to refresh the current page's
 * server-rendered data from within a Server Action: it purges the cached
 * Router Cache entry for the path so the next render reflects the new state,
 * without performing a navigation or redirect.
 */
export async function toggleNotifications() {
  preference.notificationsEnabled = !preference.notificationsEnabled

  // Revalidate the current page so it re-renders with the updated value.
  // No redirect is performed; the user stays on the same URL.
  revalidatePath('/')
}

